

function registerToolHandlers() {
  electron.ipcMain.handle("tools:list", async (_event, root) => {
    try {
      const { tools, problems } = await discover(root);
      return ok({
        tools,
        problems,
        dirs: { project: root ? projectToolsDir(root) : "", user: userToolsDir() }
      });
    } catch (error) {
      return fail(error);
    }
  });
  electron.ipcMain.handle("tools:run", async (event, root, toolId, commandId, payload = {}) => {
    try {
      const { tools } = await discover(root);
      const tool = tools.find((entry) => entry.id === toolId);
      if (!tool) return fail(`No tool called "${toolId}" is installed.`);
      const sender = event.sender;
      const emit = (message) => {
        if (!sender.isDestroyed()) sender.send("tools:event", message);
      };
      return await runTool({
        tool,
        command: commandId,
        root,
        active: payload.active ?? null,
        input: payload.input ?? "",
        emit
      });
    } catch (error) {
      return fail(error);
    }
  });
  electron.ipcMain.handle("tools:cancel", (_event, runId) => ok({ cancelled: cancelRun(runId) }));
  electron.ipcMain.handle("tools:reveal", async (_event, root, toolId) => {
    try {
      const { tools } = await discover(root);
      const tool = tools.find((entry) => entry.id === toolId);
      if (!tool) return fail(`No tool called "${toolId}" is installed.`);
      electron.shell.showItemInFolder(tool.entry);
      return ok({});
    } catch (error) {
      return fail(error);
    }
  });
  electron.ipcMain.handle("tools:scaffold", async (_event, root, name) => {
    if (!root) return fail("No project is open.");
    const id = String(name ?? "").trim().toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
    if (!SLUG.test(id)) {
      return fail("A tool name has to start with a letter and be 2 to 40 characters.");
    }
    const folder = node_path.join(projectToolsDir(root), id);
    try {
      await promises.access(folder);
      return fail(`${id} already exists.`);
    } catch {
    }
    try {
      await promises.mkdir(folder, { recursive: true });
      await promises.writeFile(node_path.join(folder, "tool.json"), manifest(id), "utf8");
      await promises.writeFile(node_path.join(folder, "tool.mjs"), starter(id), "utf8");
      return ok({ id, folder, entry: node_path.join(folder, "tool.mjs") });
    } catch (error) {
      return fail(error);
    }
  });
}
const title = (id) => id.replace(/-/g, " ").replace(/(^|\s)\w/g, (letter) => letter.toUpperCase());
const manifest = (id) => `${JSON.stringify(
  {
    id,
    name: title(id),
    description: "What this tool is for.",
    version: "0.1.0",
    entry: "tool.mjs",
    capabilities: ["editor", "ui"],
    commands: [
      {
        id: "run",
        title: `${title(id)}: run`,
        description: "Shown in the command palette."
      }
    ]
  },
  null,
  2
)}
`;
const starter = (id) => `/**
 * ${title(id)}
 *
 * Every command is one function on the default export, keyed by the id it was
 * given in tool.json. It runs in its own process; \`ctx\` is the only way back
 * to the editor, and it can only reach what tool.json declared.
 */

export default {
  async run(ctx) {
    if (!ctx.active) {
      await ctx.ui.notify('Open a file first.')
      return
    }

    const lines = ctx.active.content.split('\\n').length
    ctx.log('${id} looked at', ctx.active.relative)
    await ctx.ui.output(\`\${ctx.active.relative} — \${lines} lines\`)
  }
}
`;
const html = "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <title>Wide</title>\n    <style>\n      /*\n       * A clip, played as characters, on a flat field.\n       *\n       * There is no word on it and no mark, no version, no status line and no\n       * progress bar — the picture is the whole of it. The hairline border is\n       * the window's edge rather than content: without it the panel has no\n       * boundary against a dark desktop.\n       *\n       * Kept well below full white on purpose. At the size the cells end up\n       * this is texture, not a photograph, and texture at full contrast reads\n       * as interference.\n       */\n      * {\n        margin: 0;\n        padding: 0;\n        box-sizing: border-box;\n      }\n\n      html,\n      body {\n        width: 100%;\n        height: 100%;\n        overflow: hidden;\n      }\n\n      body {\n        display: flex;\n        align-items: center;\n        justify-content: center;\n        border: 1px solid rgba(255, 255, 255, 0.14);\n        background: #131314;\n        color: #8e8e95;\n        cursor: default;\n        user-select: none;\n        opacity: 0;\n        transition: opacity 220ms ease;\n      }\n\n      body[data-on] {\n        opacity: 1;\n      }\n\n      body[data-off] {\n        opacity: 0;\n      }\n\n      pre {\n        width: max-content;\n        font-family: 'Cascadia Mono', Consolas, 'Segoe UI Mono', monospace;\n        font-size: 8px;\n        line-height: 1.1;\n        white-space: pre;\n        /*\n         * The glyphs are a few pixels tall, and subpixel antialiasing hangs\n         * orange and blue fringes off strokes that small — colour arriving by\n         * accident, in a theme that spends it only on syntax and status.\n         *\n         * `-webkit-font-smoothing` is a no-op on Windows. What does work is\n         * giving the text its own compositing layer: Chromium cannot know what\n         * is behind a layer, so it drops to greyscale antialiasing. The opacity\n         * is a hair under 1 for exactly that reason and no other.\n         */\n        opacity: 0.999;\n        will-change: opacity;\n      }\n    </style>\n  </head>\n\n  <body>\n    <pre id=\"screen\"></pre>\n\n    <script>\n      const CLIP = '__CLIP__'\n\n      /*\n       * The reading half of `src/renderer/src/lib/ascii/format.js`, copied.\n       *\n       * This page is inlined into a data URL by `lib/splash.js` — there is no\n       * bundler behind it and no second renderer entry, so it cannot import.\n       * Copied rather than expanded at build time because the expanded frames\n       * are three times the size of the clip, and this file has to be parsed\n       * before anything appears.\n       *\n       * If the format ever changes, change it here too.\n       */\n      const DIGITS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'\n      const VALUES = {}\n      for (let i = 0; i < DIGITS.length; i += 1) VALUES[DIGITS[i]] = i\n\n      function readClip(text) {\n        const split = text.indexOf('\\n\\n')\n        const head = {}\n        for (const line of text.slice(0, split).split('\\n').slice(1)) {\n          const space = line.indexOf(' ')\n          if (space > 0) head[line.slice(0, space)] = line.slice(space + 1)\n        }\n        return {\n          cols: Number(head.cols),\n          rows: Number(head.rows),\n          fps: Number(head.fps) || 24,\n          count: Number(head.count),\n          ramp: head.ramp,\n          lines: text.slice(split + 2).split('\\n')\n        }\n      }\n\n      /* One frame from the one before it. Decoded during playback rather than\n         all at once up front: a frame costs about a millisecond, and the point\n         of this window is to be on screen before anything else is. */\n      function step(line, previous) {\n        if (!line) return previous\n        const cells = previous.split('')\n        let at = 0\n        let index = 0\n\n        const number = () => {\n          let value = 0\n          let shift = 0\n          for (;;) {\n            const digit = VALUES[line[at]]\n            at += 1\n            value |= (digit & 31) << shift\n            if ((digit & 32) === 0) return value >>> 0\n            shift += 5\n          }\n        }\n\n        while (at < line.length) {\n          index += number()\n          const length = number()\n          for (let k = 0; k < length; k += 1) cells[index + k] = line[at + k]\n          at += length\n          index += length\n        }\n        return cells.join('')\n      }\n\n      const screen = document.getElementById('screen')\n      const clip = readClip(CLIP)\n      const blank = clip.ramp[0].repeat(clip.cols * clip.rows)\n\n      /* The cell is measured rather than assumed: the ratio differs between\n         monospace faces, and a wrong one leaves the picture short of an edge. */\n      function fit() {\n        const probe = document.createElement('span')\n        probe.textContent = 'M'.repeat(50)\n        probe.style.cssText =\n          'position:absolute;visibility:hidden;white-space:pre;font:inherit;font-size:100px;line-height:1'\n        screen.appendChild(probe)\n        const ratio = probe.getBoundingClientRect().width / 50 / 100\n        probe.remove()\n\n        const line = ratio * 2\n        const size = Math.min(\n          document.body.clientWidth / (clip.cols * ratio),\n          document.body.clientHeight / (clip.rows * line)\n        )\n        screen.style.fontSize = `${size}px`\n        screen.style.lineHeight = String(line)\n      }\n\n      function show(frame) {\n        const out = []\n        for (let at = 0; at < frame.length; at += clip.cols) {\n          out.push(frame.slice(at, at + clip.cols))\n        }\n        screen.textContent = out.join('\\n')\n      }\n\n      fit()\n\n      let frame = step(clip.lines[0], blank)\n      let index = 0\n      show(frame)\n\n      requestAnimationFrame(() => document.body.setAttribute('data-on', ''))\n\n      const begun = performance.now()\n      const tick = () => {\n        const want = Math.floor(((performance.now() - begun) / 1000) * clip.fps) % clip.count\n\n        if (want < index) {\n          /* Wrapped. The deltas only run forwards, so a loop starts over from\n             the blank field rather than seeking backwards. */\n          frame = blank\n          index = -1\n        }\n        while (index < want) {\n          index += 1\n          frame = step(clip.lines[index], frame)\n        }\n        show(frame)\n        requestAnimationFrame(tick)\n      }\n      requestAnimationFrame(tick)\n\n      window.__splashOut = () => {\n        document.body.removeAttribute('data-on')\n        document.body.setAttribute('data-off', '')\n      }\n    <\/script>\n  </body>\n</html>\n";
